/**
 * Checks that a change only points at things usable from the workspace it is
 * made in: current members, the workspace's own labels, live parent issues of
 * the same project, and live top-level comments on the same issue.
 *
 * Every check throws `NotFoundError` (mapped to `not_found`), so a refused
 * reference looks the same whether it is foreign, archived, deleted or simply
 * absent. Callers run these before any write.
 */
import { isLive } from "@/lib/soft-delete";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError, requireFound } from "./_support";
import type { CommentId, IssueId, LabelId, OrgId, ProjectId, UserId } from "@/types/common";

/** A user id, when given, must belong to a current member of the workspace. */
export async function requireCurrentMember(
  orgId: OrgId,
  userId: UserId | null,
): Promise<void> {
  if (userId === null) return;
  requireFound(await memberRepo.findMember(orgId, userId), "Member", userId);
}

/** Every label id must be one of this workspace's own labels. */
export async function requireOrgLabels(
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;

  const known = new Set<string>(
    (await labelRepo.listLabels(orgId)).map((label) => label.id),
  );
  for (const labelId of labelIds) {
    if (!known.has(labelId)) throw new NotFoundError("Label", labelId);
  }
}

/** A parent issue must be a live issue of the same project in this workspace. */
export async function requireLiveParentIssue(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (!parent || !isLive(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** A reply's parent must be a live, top-level comment on the same issue. */
export async function requireTopLevelParentComment(
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = await commentRepo.findCommentById(orgId, parentId);
  if (
    !parent ||
    !isLive(parent) ||
    parent.issueId !== issueId ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
}

